What will be the output of the following code?

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add_first(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def print_list(self):
        current = self.head
        while current is not None:
            print(current.data, end=" ")
            current = current.next
        print()

if __name__ == "__main__":
    list = LinkedList()
    list.add_first(1)
    list.add_first(2)
    list.add_first(3)
    list.print_list()
```

